def link(url, label):
    return f'<a href="{esc(url, quote=True)}" target="_blank" rel="noopener noreferrer">{esc(label)} ↗</a>'


def source(path, label=None, upstream=False):
    return link((AIHOT if upstream else "../../../OpenScience/") + path, label or path)


def shot(name, caption):
    target = f"captures/{name}.png"
    image = f'<img loading="lazy" src="{target}" alt="{esc(caption)}">' if (ROOT / target).exists() else '<div class="capture-label">Implementation screenshot</div>'
    return f'<figure><a href="{target}" target="_blank">{image}</a><figcaption>{esc(caption)} · {link(target, "Open capture")}</figcaption></figure>'


def table(headers, rows):
    return '<div class="table-scroll"><table><thead><tr>' + ''.join(f'<th>{esc(h)}</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join(f'<td>{cell}</td>' for cell in row) + '</tr>' for row in rows) + '</tbody></table></div>'


