css = '''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.75 var(--font-sans)}a{color:var(--accent);text-underline-offset:3px}code{font-family:var(--font-mono);font-size:.9em;overflow-wrap:anywhere}header{background:var(--surface);border-bottom:1px solid var(--border);padding:14px 24px;position:sticky;top:0;z-index:2}header nav{max-width:1200px;margin:auto;display:flex;gap:22px;overflow:auto;white-space:nowrap;font-size:13px}main{max-width:1200px;margin:auto;padding:32px 24px 72px}section{padding:32px 0;border-bottom:1px solid var(--border);scroll-margin-top:72px}h1{font-size:32px;line-height:1.25;max-width:850px;margin:12px 0 20px}h2{font-size:23px;line-height:1.4;margin:0 0 18px}h3{font-size:17px;margin:20px 0 8px}p{margin:12px 0}.lead{font-size:19px;max-width:880px;color:var(--text-2)}.eyebrow{font-size:12px;letter-spacing:.08em;color:var(--accent);font-weight:600}.actions{display:flex;gap:20px;align-items:center;flex-wrap:wrap;margin:24px 0}.primary{background:var(--accent);color:var(--accent-fg);padding:10px 16px;border-radius:var(--radius-control);text-decoration:none}.callout{border-left:3px solid var(--accent);background:var(--accent-soft);border-radius:var(--radius-tag);padding:18px 22px;margin:24px 0}.triplet{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin:28px 0}.triplet article{border:1px solid var(--border);background:var(--surface);border-radius:var(--radius-card);padding:22px}.triplet h2{font-size:18px;margin-bottom:10px}.triplet p{font-size:14px;color:var(--text-2);margin:0}.small{font-size:13px;color:var(--text-3)}.table-scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;margin:20px 0;font-size:14px;min-width:720px}td,th{padding:15px 16px;text-align:left;vertical-align:top;border-bottom:1px solid var(--border);min-width:130px}th{background:var(--surface-2);font-size:12px;text-transform:uppercase;letter-spacing:.03em}td:first-child{font-weight:600;min-width:150px}td a{overflow-wrap:anywhere}tr:nth-child(even) td{background:var(--surface)}.gallery{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:26px 0}figure{margin:0;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-card);overflow:hidden}figure img{display:block;width:100%;height:300px;object-fit:contain;object-position:top;background:var(--surface-2)}figcaption{font-size:12px;color:var(--text-3);padding:12px 16px}.capture-label{display:flex;align-items:center;justify-content:center;min-height:180px;background:var(--surface-2);color:var(--text-3);font-size:13px}.flow{display:flex;gap:14px;align-items:center;justify-content:center;flex-wrap:wrap;margin:28px 0}.flow span{background:var(--accent-soft);color:var(--accent-strong);border:1px solid var(--border);border-radius:var(--radius-control);padding:14px 20px}.flow b{color:var(--text-3)}footer{padding-top:24px;color:var(--text-3);font-size:12px}@media(max-width:760px){main{padding:12px 16px 48px}header{padding:12px 16px}header nav{gap:18px}h1{font-size:27px}.lead{font-size:17px}.triplet,.gallery{grid-template-columns:1fr}figure img{height:340px}.flow{justify-content:flex-start}.actions{gap:14px}section{padding:24px 0}.table-scroll{margin-inline:-4px}td,th{padding:12px}}@media print{header{position:static}main{max-width:none}.table-scroll{overflow:visible}table{min-width:0}.actions{display:none}section{break-inside:auto}.gallery{break-inside:avoid}body{font-size:11px}td,th{font-size:10px;padding:8px}}'''
nav = [("decision", "Decision"), ("pages", "16 comparisons"), ("design", "Design"), ("repairs", "Corrections"), ("code", "Source"), ("integration", "Integration"), ("excluded", "Exclusions"), ("screenshots", "Screenshots"), ("acceptance", "Acceptance")]
html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>前沿动态 · source-grounded implementation review</title><style>' + tokens + css + '</style></head><body><header><nav aria-label="Review sections">' + ''.join(f'<a href="#{anchor}">{label}</a>' for anchor, label in nav) + '</nav></header><main>' + ''.join(sections) + f'<footer>Implementation branch: {BRANCH}. Initial EviMed baseline: {BASE[:12]}. Official AIHOT source: {PIN[:12]}. Review date: 2026-10-01. Historical prototype observations are explicitly separated from native implementation acceptance.</footer></main></body></html>'
(ROOT / "review.html").write_text(html)
print("Built final review.html with 16 comparisons, 14 source patterns and 12 implementation screenshot links.")
